/* netlink_priv.h - private helpers shared by netlink.c, tether.c and licence.c (defined in netlink.c).
 * Not an API: the public headers are netlink.h and licence.h. Plain C, no stb-style implementation macro.
 */
#ifndef NETMAN_NETLINK_PRIV_H
#define NETMAN_NETLINK_PRIV_H

#include <stddef.h>
#include <stdint.h>
#include <stdio.h>
#include <sys/types.h>
#include <net/if.h>
#include <linux/netlink.h>
#include <linux/rtnetlink.h>

#define NL_HDR "# generated by netman - do not edit\n"

int nl_fail(int e, const char *fmt, ...); /* sets the text netman_nl_error() returns, returns -|e| */
void nl_cpy(char *d, size_t n, const char *s);
int nl_safe_name(const char *s, size_t max);
char *nl_trim(char *s);
long nl_ms(void);
int nl_mkdirs(const char *p);
int nl_write_atomic(const char *path, const char *data, size_t len, mode_t mode);
int nl_slurp(const char *path, char *buf, size_t n);
/* fork+exec argv (no shell), optional stdin text, stderr+stdout captured into err; -ENOENT if the binary is missing */
#define NL_FAIL(...) nl_fail(-EINVAL, __VA_ARGS__)
int nl_ethtool(const char *ifn, void *data); /* SIOCETHTOOL on ifn (data is the ethtool struct); 0 or -errno */
int nl_exec(char *const argv[], const char *input, char *err, size_t errn);

struct nl_out {
	char *p;
	size_t n, cap;
};
void nl_put(struct nl_out *o, const char *fmt, ...);

typedef struct {
	int fam, plen; /* plen -1 = none given */
	unsigned char b[16];
} nl_ip;
int nl_parse_ip(const char *s, nl_ip *o, int need_plen);
int nl_iplen(const nl_ip *i);

typedef struct {
	struct nlmsghdr h;
	union {
		struct ifinfomsg i;
		struct ifaddrmsg a;
		struct rtmsg r;
	} m;
	char buf[1024];
} nl_req;
typedef void (*nl_cb)(const struct nlmsghdr *, void *);
void nl_req_init(nl_req *q, int type, int flags, size_t msglen);
void nl_attr(nl_req *q, int type, const void *d, int len);
int nl_nl(nl_req *q, nl_cb cb, void *u);
int nl_idx(const char *ifn); /* ifindex or -ENODEV */

#endif
